package com.example.incidentapp.viewmodel;
import androidx.lifecycle.*;import com.example.incidentapp.model.*;import com.example.incidentapp.repository.*;import com.example.incidentapp.session.SessionManager;import com.example.incidentapp.util.*;import java.util.*;import retrofit2.*;
public class DetalleIncidenteViewModel extends ViewModel{private final IncidenteRepository repo=new IncidenteRepository();private final CatalogoRepository cat=new CatalogoRepository();private final LocalCacheRepository local=new LocalCacheRepository();private final MutableLiveData<DetalleIncidenteResponse> detalle=new MutableLiveData<>();private final MutableLiveData<Boolean> loading=new MutableLiveData<>(false);private final MutableLiveData<Event<String>> mensaje=new MutableLiveData<>();private final MutableLiveData<Event<List<Tecnico>>> tecnicos=new MutableLiveData<>();private final MutableLiveData<Event<Boolean>> eliminado=new MutableLiveData<>();private final MutableLiveData<Event<Boolean>> anulacionSolicitada=new MutableLiveData<>();private final MutableLiveData<Event<VerificarActivoResponse>> verificacion=new MutableLiveData<>();private boolean marcandoSla;public LiveData<DetalleIncidenteResponse> getDetalle(){return detalle;}public LiveData<Boolean> getLoading(){return loading;}public LiveData<Event<String>> getMensaje(){return mensaje;}public LiveData<Event<List<Tecnico>>> getTecnicos(){return tecnicos;}public LiveData<Event<Boolean>> getEliminado(){return eliminado;}public LiveData<Event<Boolean>> getAnulacionSolicitada(){return anulacionSolicitada;}public LiveData<Event<VerificarActivoResponse>> getVerificacion(){return verificacion;}
 public void cargarDetalle(int id){int uid=SessionManager.getInstance().getIdUsuario();loading.setValue(true);repo.obtenerIncidente(id).enqueue(new Callback<DetalleIncidenteResponse>(){public void onResponse(Call<DetalleIncidenteResponse> c,Response<DetalleIncidenteResponse> r){loading.setValue(false);if(r.isSuccessful()&&r.body()!=null){detalle.setValue(r.body());local.guardarDetalle(uid,r.body());Incidente i=r.body().getIncidente();if(i!=null&&SlaUtils.estaVencidoActivo(i)&&!marcandoSla){marcandoSla=true;repo.marcarVencimientoSla(id).enqueue(new Callback<MensajeResponse>(){public void onResponse(Call<MensajeResponse> c2,Response<MensajeResponse> r2){marcandoSla=false;if(r2.isSuccessful())cargarDetalle(id);}public void onFailure(Call<MensajeResponse> c2,Throwable t){marcandoSla=false;}});}}else fallback(uid,id,"No se pudo obtener el detalle");}public void onFailure(Call<DetalleIncidenteResponse> c,Throwable t){loading.setValue(false);fallback(uid,id,"Sin conexión · mostrando detalle guardado");}});}private void fallback(int uid,int id,String msg){local.cargarDetalle(uid,id,d->{if(d!=null)detalle.setValue(d);mensaje.setValue(new Event<>(d==null?"Sin conexión y sin detalle guardado":msg));});}
 private Callback<MensajeResponse> recargar(int id,String ok,String fail){return new Callback<MensajeResponse>(){public void onResponse(Call<MensajeResponse> c,Response<MensajeResponse> r){loading.setValue(false);if(r.isSuccessful()){mensaje.setValue(new Event<>(r.body()==null?ok:r.body().getMensaje()));cargarDetalle(id);}else mensaje.setValue(new Event<>(ApiErrorUtils.obtenerMensaje(r,fail)));}public void onFailure(Call<MensajeResponse> c,Throwable t){loading.setValue(false);mensaje.setValue(new Event<>("No se pudo conectar con la API"));}};}
 public void cambiarEstado(int id,String e,String c){loading.setValue(true);repo.cambiarEstado(id,e,c).enqueue(recargar(id,"Estado actualizado","No se pudo cambiar el estado"));} public void cambiarPrioridad(int id,String p,String c){loading.setValue(true);repo.cambiarPrioridad(id,p,c).enqueue(recargar(id,"Prioridad actualizada","No se pudo cambiar la prioridad"));} public void cargarTecnicos(){cat.obtenerTecnicos().enqueue(new Callback<TecnicosResponse>(){public void onResponse(Call<TecnicosResponse> c,Response<TecnicosResponse> r){if(r.isSuccessful()&&r.body()!=null)tecnicos.setValue(new Event<>(r.body().getTecnicos()==null?Collections.emptyList():r.body().getTecnicos()));else mensaje.setValue(new Event<>(ApiErrorUtils.obtenerMensaje(r,"No se pudieron obtener los técnicos")));}public void onFailure(Call<TecnicosResponse> c,Throwable t){mensaje.setValue(new Event<>("No se pudo conectar con la API"));}});} public void asignarTecnico(int id,int tid){loading.setValue(true);repo.asignarTecnico(id,tid).enqueue(recargar(id,"Técnico asignado","No se pudo asignar el técnico"));} public void verificarActivo(int id,String qr){loading.setValue(true);repo.verificarActivo(id,qr).enqueue(new Callback<VerificarActivoResponse>(){public void onResponse(Call<VerificarActivoResponse> c,Response<VerificarActivoResponse> r){loading.setValue(false);if(r.body()!=null&&(r.isSuccessful()||r.code()==409))verificacion.setValue(new Event<>(r.body()));else mensaje.setValue(new Event<>(ApiErrorUtils.obtenerMensaje(r,"No se pudo verificar el activo")));}public void onFailure(Call<VerificarActivoResponse> c,Throwable t){loading.setValue(false);mensaje.setValue(new Event<>("No se pudo conectar con la API"));}});} public void solicitarAnulacion(int id,String m){loading.setValue(true);repo.solicitarAnulacion(id,m).enqueue(new Callback<MensajeResponse>(){public void onResponse(Call<MensajeResponse> c,Response<MensajeResponse> r){loading.setValue(false);if(r.isSuccessful()){mensaje.setValue(new Event<>(r.body()==null?"Solicitud enviada":r.body().getMensaje()));anulacionSolicitada.setValue(new Event<>(true));cargarDetalle(id);}else mensaje.setValue(new Event<>(ApiErrorUtils.obtenerMensaje(r,"No se pudo enviar la solicitud")));}public void onFailure(Call<MensajeResponse> c,Throwable t){loading.setValue(false);mensaje.setValue(new Event<>("No se pudo conectar con la API"));}});} public void eliminarIncidente(int id,String m){loading.setValue(true);repo.eliminarIncidente(id,m).enqueue(new Callback<MensajeResponse>(){public void onResponse(Call<MensajeResponse> c,Response<MensajeResponse> r){loading.setValue(false);if(r.isSuccessful()){mensaje.setValue(new Event<>(r.body()==null?"Incidente eliminado":r.body().getMensaje()));eliminado.setValue(new Event<>(true));}else mensaje.setValue(new Event<>(ApiErrorUtils.obtenerMensaje(r,"No se pudo eliminar el incidente")));}public void onFailure(Call<MensajeResponse> c,Throwable t){loading.setValue(false);mensaje.setValue(new Event<>("No se pudo conectar con la API"));}});}}
